<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api } from './session'
import { formatDate } from './domain'
interface Event { id: string; actor_name: string; actor_user_id: string; action: string; object_type: string; object_id: string; occurred_at: string; details: Record<string, string | number | boolean> }
const events = ref<Event[]>([]), total = ref(0), page = ref(1), loading = ref(false), error = ref('')
const actions = ref<string[]>([]), kinds = ref<string[]>([]), actors = ref<{ id: string; name: string }[]>([])
const action = ref(''), kind = ref(''), actor = ref(''), from = ref(''), to = ref('')
let filters = new URLSearchParams(), generation = 0
const names: Record<string, string> = { 'auth.login': 'Вход сотрудника', 'auth.logout': 'Выход сотрудника', 'question.publish': 'Публикация вопроса', 'question.create': 'Создание вопроса', 'question.version.create': 'Новая версия вопроса', 'question.archive': 'Архивирование вопроса', 'test.publish': 'Публикация теста', 'test.create': 'Создание теста', 'test.version.create': 'Новая версия теста', 'test.archive': 'Архивирование теста', 'category.create': 'Создание категории', 'category.update': 'Изменение категории', 'category.delete': 'Удаление категории', 'candidate.create': 'Создание кандидата', 'candidate.update': 'Изменение кандидата', 'candidate.contacts.erase': 'Удаление контактных данных', 'candidate.retention_hold': 'Изменение запрета очистки', 'vacancy.create': 'Создание вакансии', 'vacancy.update': 'Изменение вакансии', 'invitation.issue': 'Выдача приглашения', 'invitation.revoke': 'Отзыв приглашения', 'attempt.start': 'Начало попытки', 'attempt.submitted': 'Завершение попытки', 'attempt.expired': 'Истечение времени', 'result.view': 'Просмотр отчёта', 'result.export': 'Экспорт результата', 'team.member.create': 'Добавление сотрудника', 'team.member.update': 'Изменение прав сотрудника', 'retention.policy.update': 'Изменение правил хранения', 'retention.preview': 'Предпросмотр очистки', 'retention.apply': 'Применение очистки' }
const detailNames: Record<string, string> = { format: 'Формат', row_count: 'Строк', date_from: 'Дата с', date_to: 'Дата по', policy_revision: 'Версия правил', candidates_erased: 'Карточек очищено', candidates_skipped: 'Карточек пропущено', audit_events_deleted: 'Событий удалено', hold: 'Запрет очистки' }
async function load() { const current = ++generation; loading.value = true; error.value = ''; try { const query = new URLSearchParams(filters); query.set('page', String(page.value)); const data = await api<{ items: Event[]; total: number }>('/audit?' + query); if (current === generation) { events.value = data.items; total.value = data.total } } catch (err) { if (current === generation) { events.value = []; error.value = (err as Error).message } } finally { if (current === generation) loading.value = false } }
function filter() { filters = new URLSearchParams({ action: action.value, object_type: kind.value, actor_id: actor.value, date_from: from.value, date_to: to.value }); page.value = 1; void load() }
onMounted(async () => { void load(); try { const options = await api<{ actions: string[]; object_types: string[]; actors: { id: string; name: string }[] }>('/audit/options'); actions.value = options.actions; kinds.value = options.object_types; actors.value = options.actors } catch (err) { error.value = (err as Error).message } })
</script>
<template>
  <div class="page-heading"><div><p class="eyebrow">КОНТРОЛЬ ДЕЙСТВИЙ</p><h1>Журнал аудита</h1><p class="subtitle">Действия вашей организации. Даты фильтров по МСК.</p></div><button class="secondary-button" :disabled="loading" @click="load">Обновить</button></div>
  <form class="result-filters" @submit.prevent="filter"><label>Действие<select v-model="action" aria-label="Действие аудита"><option value="">Все действия</option><option v-for="value in actions" :key="value" :value="value">{{ names[value] || value }}</option></select></label><label>Объект<select v-model="kind" aria-label="Тип объекта аудита"><option value="">Все объекты</option><option v-for="value in kinds" :key="value" :value="value">{{ value }}</option></select></label><label>Сотрудник<select v-model="actor" aria-label="Сотрудник аудита"><option value="">Все исполнители</option><option value="system">Система</option><option v-for="value in actors" :key="value.id" :value="value.id">{{ value.name }}</option></select></label><label>Дата с<input v-model="from" type="date" aria-label="Дата аудита с" /></label><label>Дата по<input v-model="to" type="date" aria-label="Дата аудита по" /></label><button class="primary-button" :disabled="loading">Применить фильтры</button></form>
  <p v-if="error" class="form-error" role="alert">{{ error }}</p><p v-if="loading" role="status">Загружаем события…</p>
  <section v-else-if="events.length" class="audit-list" aria-label="События аудита"><article v-for="event in events" :key="event.id" class="audit-card"><div><h2>{{ names[event.action] || event.action }}</h2><p>{{ event.actor_name }} · {{ formatDate(event.occurred_at) }}</p></div><p class="muted-text">{{ event.object_type }}<span v-if="event.object_id"> · {{ event.object_id }}</span></p><dl v-if="Object.keys(event.details).length" class="audit-details"><div v-for="(value, key) in event.details" :key="key"><dt>{{ detailNames[key] || key }}</dt><dd>{{ typeof value === 'boolean' ? value ? 'Да' : 'Нет' : value }}</dd></div></dl><p class="muted-text audit-code">{{ event.action }} · событие {{ event.id }}</p></article></section><section v-else class="empty-state"><h2>Событий не найдено</h2><p>Измените фильтры.</p></section>
  <div class="passage-actions"><button class="secondary-button" :disabled="loading || page <= 1" @click="page--; load()">Назад</button><span>Страница {{ page }} · всего {{ total }}</span><button class="secondary-button" :disabled="loading || page * 50 >= total" @click="page++; load()">Далее</button></div>
</template>
